-- Faculty records for the future AdminFaculty back office.
-- The current site still reads a static list in src/content/faculty.ts.
-- Supabase is reached from the server only. The service role bypasses RLS.
-- anon and authenticated have no policies, so they cannot read or write this table.

create table public.faculty (
  -- Stable identifier generated by Postgres. Not taken from the old string ids.
  id uuid primary key default gen_random_uuid(),
  -- Display name, required.
  name text not null,
  -- Academic title (for example Associate Professor). Optional.
  title text,
  -- Degree and institution. Optional.
  education text,
  -- Research or teaching fields, stored as one text value. Optional.
  research_fields text,
  email text,
  phone text,
  website text,
  -- Public URL of a portrait. Optional. The file itself is not stored here.
  image_url text,
  -- full-time, visiting, or adjunct. Null is allowed until a category is chosen.
  category text check (category in ('full-time', 'visiting', 'adjunct')),
  -- Lower numbers appear first in the public list.
  sort_order integer default 0,
  created_at timestamptz default now()
);

comment on table public.faculty is
  'Faculty directory. Written only by server-side Supabase access. No public write policy.';

comment on column public.faculty.id is
  'Primary key. Generated with gen_random_uuid().';

comment on column public.faculty.category is
  'One of full-time, visiting, adjunct.';

comment on column public.faculty.sort_order is
  'Display order. Defaults to 0.';

-- Turn on row level security. With no policies, the public roles are denied.
alter table public.faculty enable row level security;

-- Intentionally no INSERT, UPDATE, DELETE, or SELECT policy for anon or authenticated.
-- Do not add a public write policy. Server code uses the service role, which bypasses RLS.
